import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"通义灵码上手","description":"从零装上通义灵码 / Qoder CN：独立 IDE 或 IDE 插件，登录阿里云账号，用上补全和三种智能会话。","frontmatter":{"title":"通义灵码上手","description":"从零装上通义灵码 / Qoder CN：独立 IDE 或 IDE 插件，登录阿里云账号，用上补全和三种智能会话。","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/lingma/lingma.md","filePath":"zh/products/lingma/lingma.md","lastUpdated":1787110548000}'),l={name:"zh/products/lingma/lingma.md"};function n(i,t,d,s,h,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="通义灵码上手" tabindex="-1">通义灵码上手 <a class="header-anchor" href="#通义灵码上手" aria-label="Permalink to &quot;通义灵码上手&quot;">​</a></h1><blockquote><p>这是一份<strong>教程</strong>。按顺序做完：分清形态 → 抄官方安装 → 登录 → 行间补全 → 三种会话。</p><p>名词看 <a href="./lingma-glossary.html">术语表</a>；快捷键和套餐看 <a href="./lingma-cheatsheet.html">Cheatsheet</a>；场景配方看 <a href="./lingma-cookbook.html">Cookbook</a>。</p></blockquote><p>本指南目标：把通义灵码从「听说过国内 Copilot」用成「在 IDE 里能补全、能问、能改」。</p><h2 id="第-0-步-先确认你在装哪一个" tabindex="-1">第 0 步：先确认你在装哪一个 <a class="header-anchor" href="#第-0-步-先确认你在装哪一个" aria-label="Permalink to &quot;第 0 步：先确认你在装哪一个&quot;">​</a></h2><p>官方帮助中心把编码子产品叫 <strong>Qoder CN</strong>（原通义灵码），并提供两种使用方式（<a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">安装指南</a>）：</p><blockquote><p>Qoder CN 为您提供两种使用方式。您可以选择下载开箱即用的 Qoder CN IDE，也可以选择在您现有的开发工具中直接安装 Qoder CN 插件。安装后登录账号即可开始使用。</p></blockquote><table tabindex="0"><thead><tr><th>你已有的环境</th><th>装什么</th><th>官方态度</th></tr></thead><tbody><tr><td>没有偏好 / 想要 AI 原生 IDE</td><td><strong>Qoder CN IDE</strong>（营销站仍写 Lingma IDE）</td><td>现行主推</td></tr><tr><td>IntelliJ IDEA / WebStorm / PyCharm 等</td><td><strong>JetBrains 插件</strong></td><td>现行迭代面</td></tr><tr><td>VS Code</td><td><strong>VS Code 插件</strong></td><td>仍可装，但官方已写更新放缓 / 停止维护</td></tr><tr><td>Visual Studio 2022 / 2019</td><td><strong>Visual Studio 插件</strong></td><td>智能会话暂仅问答</td></tr></tbody></table><p>个人版前提：已注册阿里云账号，用主账号登录个人版（<a href="https://help.aliyun.com/zh/lingma/individual-edition-quick-start" target="_blank" rel="noreferrer">个人版快速入门</a>）。</p><h2 id="第-1-步-装上" tabindex="-1">第 1 步：装上 <a class="header-anchor" href="#第-1-步-装上" aria-label="Permalink to &quot;第 1 步：装上&quot;">​</a></h2><p>下面安装步骤<strong>逐字抄官方</strong>，不改搜索词、不合成新旧品牌名。打开哪一页，就按那一页搜。</p><h3 id="_1-1-独立-ide" tabindex="-1">1.1 独立 IDE <a class="header-anchor" href="#_1-1-独立-ide" aria-label="Permalink to &quot;1.1 独立 IDE&quot;">​</a></h3><p>营销站 <a href="https://lingma.aliyun.com/download" target="_blank" rel="noreferrer">lingma.aliyun.com/download</a> 原文：</p><blockquote><p>Lingma IDE 将增强上下文工程与智能体无缝集成，全面理解代码库，轻松处理复杂任务，同时兼容 JetBrains IDEs 等主流编程工具，开发者可以自由选择。</p><p>全面集成智能编码助手的能力，开箱即用更简单，无需安装插件即可享受高效、智能的编程体验。</p></blockquote><p>该页列出的系统门槛：</p><ul><li><strong>macOS</strong> 11.0+</li><li><strong>Windows</strong> 10/11</li><li><strong>Linux</strong> <code>.deb</code> / <code>.rpm</code></li></ul><p>帮助中心安装指南把同一产品写成 <strong>Qoder CN IDE</strong>，下载地址指向 <a href="https://qoder.com.cn/download" target="_blank" rel="noreferrer">https://qoder.com.cn/download</a>，并写：</p><blockquote><p>适用操作系统：Windows 10/11（x64）、macOS 11.0 、Linux x64 (.deb/.rpm) 或更新版本。</p></blockquote><p>两站都是官方入口。新品牌下载走 <code>qoder.com.cn/download</code>；旧品牌页仍挂 Lingma IDE 安装包。升级路径官方写过：卸载原 Lingma IDE，再安装 Qoder CN IDE（<a href="https://help.aliyun.com/zh/lingma/billing-description" target="_blank" rel="noreferrer">计费说明</a>）。</p><h3 id="_1-2-jetbrains-插件" tabindex="-1">1.2 JetBrains 插件 <a class="header-anchor" href="#_1-2-jetbrains-插件" aria-label="Permalink to &quot;1.2 JetBrains 插件&quot;">​</a></h3><p>营销站 <a href="https://lingma.aliyun.com/download" target="_blank" rel="noreferrer">下载和安装</a> 以 IntelliJ IDEA 为例，原文：</p><blockquote><p><strong>方式一：从插件市场安装</strong></p><p>点击导航-插件，打开应用市场，搜索通义灵码（TONGYI Lingma），找到通义灵码后点击安装。</p><p><strong>方式二：下载离线包安装</strong></p><ol><li>下载 JetBrains IDEs 的 zip 安装包；</li><li>点击导航-插件，点击设置图标，下拉菜单中单击从本地安装插件，选择下载的 zip 文件后安装。</li></ol><p>重启 IntelliJ IDEA，重启成功后登录阿里云账号，即刻开启智能编码之旅。</p></blockquote><p>帮助中心同一流程改用新名，原文：</p><blockquote><p>打开 IntelliJ IDEA 设置窗口，在插件市场中搜索 Qoder CN，找到 Qoder CN 后单击安装。</p><p>安装完成后，请重启 IntelliJ IDEA。</p></blockquote><p>离线包官方链接（帮助中心）：<a href="https://tongyi-code.oss-cn-hangzhou.aliyuncs.com/jetbrain/tongyi-jetbrains-latest.zip" target="_blank" rel="noreferrer">Qoder CN - JetBrains</a>。新品牌下载页另给：<a href="https://qodercn-jb.oss-cn-hangzhou.aliyuncs.com/qodercn-jetbrains-latest.zip" target="_blank" rel="noreferrer">qodercn-jetbrains-latest.zip</a>。</p><p>兼容范围见 <a href="./lingma-cheatsheet.html#兼容-ide-和系统">Cheatsheet · 兼容</a>。帮助中心写 JetBrains IDEs <strong>2020.3 及以上</strong>。</p><h3 id="_1-3-visual-studio-code-插件" tabindex="-1">1.3 Visual Studio Code 插件 <a class="header-anchor" href="#_1-3-visual-studio-code-插件" aria-label="Permalink to &quot;1.3 Visual Studio Code 插件&quot;">​</a></h3><p>先读官方态度，再决定要不要装：</p><blockquote><p>产品功能迭代将主要集中在 Qoder CN IDE 和 Qoder CN JetBrains 插件中，VSCode 插件更新节奏将会放缓。如果您在使用 VSCode 插件过程中遇到问题或不便，建议切换到 Qoder CN IDE。（<a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">安装指南</a>）</p></blockquote><p>帮助中心安装原文：</p><blockquote><p>下载并安装 Visual Studio Code <strong>1.68.0 及以上版本</strong>。</p><p><strong>方法 1：从插件市场安装</strong></p><p>单击 <a href="vscode:extension/Alibaba-Cloud.tongyi-lingma" target="_blank" rel="noreferrer">立即安装</a> ，唤起 Visual Studio Code 插件市场直接安装，安装后请重启 IDE，即可开启智能编码之旅。</p><p>打开 Visual Studio Code 扩展窗口，搜索 Qoder CN，找到 Qoder CN 后单击安装。</p><p><strong>方法 2：下载安装包安装</strong></p><p>单击下方链接，下载 Visual Studio Code 的 VSIX 安装包：<a href="https://tongyi-code.oss-cn-hangzhou.aliyuncs.com/vscode/tongyi-lingma-latest.vsix" target="_blank" rel="noreferrer">Qoder CN-VS Code</a></p><p>打开 Visual Studio Code 后，单击扩展，单击更多按钮，在下拉菜单中单击 <strong>从 VSIX 安装</strong> ，选择下载的 VSIX 文件后安装。</p><p>安装完成后，请重启 Visual Studio Code。</p></blockquote><p>市场扩展 ID 仍是 <code>Alibaba-Cloud.tongyi-lingma</code>，展示名 <strong>Qoder CN (Formerly Lingma)</strong>。</p><p>侧栏找不到入口时，官方原文：</p><blockquote><p>如果安装后在侧边导航上找不到 Qoder CN 入口，可鼠标聚焦在侧边导航后右键查看，勾选 Qoder CN 后即可将插件入口配置在侧边导航上。</p></blockquote><h3 id="_1-4-visual-studio" tabindex="-1">1.4 Visual Studio <a class="header-anchor" href="#_1-4-visual-studio" aria-label="Permalink to &quot;1.4 Visual Studio&quot;">​</a></h3><p>帮助中心没有单独逐步截图，只写「通过插件市场或下载安装包进行安装」（<a href="https://help.aliyun.com/zh/lingma/installation-and-login-guide/" target="_blank" rel="noreferrer">安装和登录</a>）。兼容版本：Visual Studio <strong>2022 17.3.0 及以上</strong>，或 <strong>2019 16.3.0 及以上</strong>；操作系统 Windows 10 及以上（<a href="https://help.aliyun.com/zh/lingma/compatible-ide-and-system" target="_blank" rel="noreferrer">兼容 IDE 和系统</a>）。智能会话在 Visual Studio 上<strong>暂仅支持智能问答</strong>（<a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">智能会话概览</a>）。</p><p>逐步点选找不到官方原文，这里不编。以 <a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">安装指南</a> 为准。</p><h2 id="第-2-步-登录" tabindex="-1">第 2 步：登录 <a class="header-anchor" href="#第-2-步-登录" aria-label="Permalink to &quot;第 2 步：登录&quot;">​</a></h2><p>个人版官方步骤（<a href="https://help.aliyun.com/zh/lingma/individual-edition-quick-start" target="_blank" rel="noreferrer">个人版快速入门</a>）：</p><blockquote><ol><li>安装完成后，选择 阿里云中国站账号登录 ，前往阿里云登录页完成登录。</li><li>在阿里云登录页面完成登录，后续即可看到登录成功页面。</li><li>回到 IDE 端即可开始使用 Qoder CN 。</li></ol><p>登录成功页面将展示账号名称和 Account ID 等信息。在 IDE 中，可通过 TONGYI Lingma 插件面板右上角的账号名称确认登录状态。</p></blockquote><p>帮助中心还写：可通过阿里云登录页或 <strong>AK/SK</strong> 登录（远程开发常见）。企业标准版 / 专属版登录入口不同，见 <a href="https://help.aliyun.com/zh/lingma/installation-and-login-guide/" target="_blank" rel="noreferrer">安装和登录</a>，本教程不展开企业控制台。</p><h2 id="第-3-步-行间代码补全" tabindex="-1">第 3 步：行间代码补全 <a class="header-anchor" href="#第-3-步-行间代码补全" aria-label="Permalink to &quot;第 3 步：行间代码补全&quot;">​</a></h2><p>打开一个真实前端文件，开始打字。官方定义（<a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">什么是 Qoder CN</a>）：</p><blockquote><p>根据当前语法和跨文件的代码上下文，自动感知当前工程，实时生成行、函数级代码。</p><p>通过注释描述您想要的功能，可直接在编辑器区生成代码。</p></blockquote><p>接受建议用 <strong>Tab</strong>（<a href="https://help.aliyun.com/zh/lingma/plug-in-configuration-guide" target="_blank" rel="noreferrer">插件配置</a>）。想让补全对准意图，把目标写进注释，而不是写「处理一下」。</p><p>行间建议预测（NES）是下一处修改的预测，不是同一件事，见 <a href="./lingma-cookbook.html#打开行间建议预测-nes">Cookbook</a>。</p><h2 id="第-4-步-智能会话-先学会选模式" tabindex="-1">第 4 步：智能会话，先学会选模式 <a class="header-anchor" href="#第-4-步-智能会话-先学会选模式" aria-label="Permalink to &quot;第 4 步：智能会话，先学会选模式&quot;">​</a></h2><p>唤起会话（<a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">智能会话概览</a>）：</p><table tabindex="0"><thead><tr><th>操作</th><th>macOS</th><th>Windows</th></tr></thead><tbody><tr><td>打开 / 关闭智能会话</td><td><code>⌘ ⇧ L</code>（JetBrains、VS Code）；<code>⌘ L</code>（Lingma IDE）</td><td><code>Ctrl Shift L</code></td></tr></tbody></table><p>官方三种模式，一次会话里可切换，<strong>不必新建会话</strong>：</p><table tabindex="0"><thead><tr><th>模式</th><th>官方定义</th><th>选它的信号</th></tr></thead><tbody><tr><td><strong>智能问答</strong></td><td>纯研发问答；结合上下文给方案，<strong>不会直接改工程文件</strong></td><td>我要先搞懂</td></tr><tr><td><strong>文件编辑</strong></td><td>精准多文件修改，可迭代、可审查</td><td>我知道改哪，要看 diff</td></tr><tr><td><strong>智能体</strong></td><td>自主决策、感知工程、用工具（含终端、MCP），端到端完成任务</td><td>我只给目标，过程交给它</td></tr></tbody></table><p>支持矩阵也是官方写死的，不要假设全家都能用三种模式：</p><ul><li><strong>Visual Studio Code</strong>：三种都支持</li><li><strong>Lingma IDE / JetBrains 插件</strong>：智能问答 + 智能体；<strong>不支持文件编辑</strong></li><li><strong>Visual Studio</strong>：智能会话暂仅智能问答</li><li>体验最新能力：VS Code / JetBrains 需升到 <strong>2.5.0 或以上</strong></li></ul><p>输入需求的官方建议（不要改写成「一般可以」）：</p><blockquote><ul><li>结构化地描述需求：包含一个明确的目标，并通过步骤式的结构化描述。</li><li>给出相关的上下文：代码文件、图片、codebase、codeChanges 等。</li><li>明确生成要求：语言、规范、格式、变更目标。</li><li>多多互动，逐步迭代。</li></ul></blockquote><p>文件编辑 / 智能体产生的改动要在 diff 里接受或拒绝。接受后才合并进原文件。</p><h2 id="第-5-步-让智能体干活时盯住终端确认" tabindex="-1">第 5 步：让智能体干活时盯住终端确认 <a class="header-anchor" href="#第-5-步-让智能体干活时盯住终端确认" aria-label="Permalink to &quot;第 5 步：让智能体干活时盯住终端确认&quot;">​</a></h2><p>智能体模式会自己拆任务、改多文件、跑终端。官方默认（<a href="https://help.aliyun.com/zh/lingma/agent" target="_blank" rel="noreferrer">智能体</a>）：</p><blockquote><p>默认每次执行命令前需要开发者进行确认：单击 <strong>运行</strong> 发送到 IDE Terminal；单击 <strong>取消</strong> 跳过此次命令。</p></blockquote><p>不要第一天就打开自动执行白名单。MCP 也是每次执行前询问。配方见 <a href="./lingma-cookbook.html">Cookbook</a>。</p><h2 id="第-6-步-安全习惯" tabindex="-1">第 6 步：安全习惯 <a class="header-anchor" href="#第-6-步-安全习惯" aria-label="Permalink to &quot;第 6 步：安全习惯&quot;">​</a></h2><ul><li><strong>审查生成代码</strong>，尤其是权限、鉴权、支付、SQL 拼接。</li><li>智能体跑终端时，<strong>看不懂的命令不要点运行</strong>。</li><li>企业知识库 / 私域代码增强是企业版能力，个人版不要假设已经接上。</li><li>本站不写模型内部机制；模型原理见 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a>。</li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>选错模式、提示写不明白、要接 MCP → <a href="./lingma-cookbook.html">Cookbook</a></li><li>查安装 URL / 快捷键 / 套餐 → <a href="./lingma-cheatsheet.html">Cheatsheet</a></li><li>搞不清更名和「不是什么」 → <a href="./lingma-glossary.html">术语表</a></li></ul><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">安装指南</a></li><li><a href="https://lingma.aliyun.com/download" target="_blank" rel="noreferrer">下载和安装（营销站）</a></li><li><a href="https://help.aliyun.com/zh/lingma/individual-edition-quick-start" target="_blank" rel="noreferrer">个人版快速入门</a></li><li><a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">智能会话概览</a></li><li><a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">什么是 Qoder CN</a></li></ul>',65)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
